css:
#tongsci1-3-3-3-1-codon .cd-body { grid-template-columns: 1120px minmax(0, 1fr); }
#tongsci1-3-3-3-1-codon .cd-stage { position: relative; border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; background: #ece6f6; }
#tongsci1-3-3-3-1-codon .cd-stage canvas { touch-action: none; cursor: grab; user-select: none; -webkit-user-select: none; }
#tongsci1-3-3-3-1-codon .cd-stage .now-chip { top: auto; bottom: 128px; left: 14px; font-size: 17px; padding: 6px 14px; }
#tongsci1-3-3-3-1-codon .cd-panel { gap: 12px; }
#tongsci1-3-3-3-1-codon .cd-out { margin: 0; font-size: 19px; line-height: 1.5; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 10px 14px; min-height: 7.6em; flex: none; }
#tongsci1-3-3-3-1-codon .cd-out b { color: var(--accent); }
#tongsci1-3-3-3-1-codon .cd-def { margin: 0; display: grid; gap: 7px; flex: none; }
#tongsci1-3-3-3-1-codon .cd-def div { border-left: 6px solid #6b4f96; background: color-mix(in srgb, #6b4f96 9%, var(--paper-2)); border-radius: 0 10px 10px 0; padding: 5px 12px; }
#tongsci1-3-3-3-1-codon .cd-def dt { font: 800 18px var(--f-body); color: #4b2f80; }
#tongsci1-3-3-3-1-codon .cd-def dd { margin: 1px 0 0; font-size: 16px; line-height: 1.42; }
section#tongsci1-3-3-3-1-codon.ex.u-done .cd-def { display: none; }
#tongsci1-3-3-3-1-codon .u-learn p { font-size: 19px; line-height: 1.5; }

